void intesort(List<int> arr, int Function(int, int) compare) {
  for (int i = 1; i < arr.length; i++) {
    int key = arr[i];
    int j = i - 1;


    while (j >= 0 && compare(arr[j], key) > 0) {
      arr[j + 1] = arr[j];
      j--;
    }
    arr[j + 1] = key;
  }
}

